[CmdletBinding()]
param(
  [Parameter(Mandatory=$true)][string]$AnalysisPath,
  [Parameter(Mandatory=$true)][string]$ReportPath,
  [Parameter(Mandatory=$true)][string]$ChartDirectory,
  [Parameter(Mandatory=$true)][string]$TimestampPath
)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$a=Get-Content $AnalysisPath -Raw|ConvertFrom-Json
if($a.schema-ne2){throw 'Expected offline analysis schema 2'}
$timestamps=Get-Content $TimestampPath -Raw|ConvertFrom-Json
if(!$timestamps.passed-or$timestamps.mode-ne'render-graph-gpu-timestamps'){throw 'Expected accepted render-graph GPU timestamps'}
$recordedArchitecture=if([string]$a.capture.architecture){[string]$a.capture.architecture}elseif([string]$timestamps.architecture){[string]$timestamps.architecture}else{'ARM64'}
$architecture=if($recordedArchitecture-eq'AMD64'){'x64'}else{$recordedArchitecture}
$etlCount=@($a.traces|Where-Object{$_.etl.available-or[double]$_.etl.bytes-gt0}).Count
[void][IO.Directory]::CreateDirectory($ChartDirectory)
Get-ChildItem $ChartDirectory -File -Filter '*.png' -ErrorAction SilentlyContinue|Remove-Item -Force
$labels=[ordered]@{'d3d12-raster'='D3D12 Raster';'d3d12-compute'='D3D12 Compute';'wgsl-raster'='WGSL Raster';'wgsl-compute'='WGSL Compute';'spirv-raster'='SPIR-V Raster';'spirv-compute'='SPIR-V Compute'}
$colors=[ordered]@{'d3d12-raster'='#28708A';'d3d12-compute'='#C6533C';'wgsl-raster'='#33845F';'wgsl-compute'='#B47722';'spirv-raster'='#5D5AA8';'spirv-compute'='#AD4770'}
function F([double]$v,[int]$d=2){$v.ToString("F$d",[Globalization.CultureInfo]::InvariantCulture)}
function Html([object]$v){[Net.WebUtility]::HtmlEncode([string]$v)}
function Cell([string]$n){@($a.cells|Where-Object cell -EQ $n)[0]}
function Trace([string]$n){@($a.traces|Where-Object cell -EQ $n)[0]}
function Median([double[]]$values){$sorted=@($values|Sort-Object);if(!$sorted.Count){return $null};$middle=[math]::Floor($sorted.Count/2);if($sorted.Count%2){return [double]$sorted[$middle]};([double]$sorted[$middle-1]+[double]$sorted[$middle])/2}
function TimestampRun([string]$n){$runs=@($timestamps.runs|Where-Object cell -EQ $n);if(!$runs.Count){return $null};$names=@($runs[0].passes.name);foreach($run in $runs){$runNames=@($run.passes.name);if($runNames.Count-ne$names.Count-or@(Compare-Object $names $runNames).Count){throw "Pass structure mismatch: $n"}};$passes=@(foreach($name in $names){$values=@($runs|ForEach-Object{[double]@($_.passes|Where-Object name -EQ $name)[0].medianGpuMs});[pscustomobject]@{name=$name;medianGpuMs=Median $values}});[pscustomobject]@{medianGpuMs=Median @($runs|ForEach-Object{[double]$_.medianGpuMs});passes=$passes}}
function Startup([string]$n,[string]$s){@($a.startup|Where-Object{$_.cell-eq$n-and$_.state-eq$s})[0]}
function Scope($s,[string]$n){$p=$s.shaderScopes.PSObject.Properties[$n];if($p){[double]$p.Value}else{0.0}}
function Chart([string]$path,[string]$title,[object[]]$items,[double]$max,[string]$unit,[string]$note){$w=1920;$h=1080;$bmp=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bmp);$g.SmoothingMode='AntiAlias';$g.Clear([Drawing.ColorTranslator]::FromHtml('#F5F7F8'));$tf=[Drawing.Font]::new('Segoe UI',30,[Drawing.FontStyle]::Bold);$f=[Drawing.Font]::new('Segoe UI',17);$sf=[Drawing.Font]::new('Segoe UI',13);$g.DrawString($title,$tf,[Drawing.Brushes]::Black,80,38);$l=170;$t=130;$r=1840;$b=890;$grid=[Drawing.Pen]::new([Drawing.ColorTranslator]::FromHtml('#D5DDE1'),1);for($i=0;$i-le5;$i++){$v=$max*$i/5;$y=$b-($b-$t)*$i/5;$g.DrawLine($grid,$l,$y,$r,$y);$g.DrawString("$(F $v 1) $unit",$sf,[Drawing.Brushes]::DimGray,45,$y-10)};$gw=($r-$l)/$items.Count;for($i=0;$i-lt$items.Count;$i++){$it=$items[$i];$x=$l+$i*$gw+$gw*.2;$bw=$gw*.6;$bh=[double]$it.value/$max*($b-$t);$y=$b-$bh;$brush=[Drawing.SolidBrush]::new([Drawing.ColorTranslator]::FromHtml($it.color));$g.FillRectangle($brush,$x,$y,$bw,$bh);$brush.Dispose();$g.DrawString((F $it.value 3),$f,[Drawing.Brushes]::Black,$x,$y-32);$g.DrawString($it.label,$sf,[Drawing.Brushes]::Black,$x-18,$b+18)};$g.DrawString($note,$sf,[Drawing.Brushes]::DimGray,170,1000);$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);$grid.Dispose();$tf.Dispose();$f.Dispose();$sf.Dispose();$g.Dispose();$bmp.Dispose()}
$order=@('d3d12-raster','d3d12-compute','wgsl-raster','wgsl-compute','spirv-raster','spirv-compute')
$items=@($order|ForEach-Object{$c=Cell $_;[pscustomobject]@{label=$labels[$_];value=[double]$c.completedFrameMs.median;color=$colors[$_]}})
Chart (Join-Path $ChartDirectory 'offline-five-run-frame-time.png') 'Frame 3000: five-run GPU-drained offline throughput' $items 21 'ms/frame' 'Lower is better. Command recording/submission and GPU completion are included; final queue is drained.'
$items=@($order|ForEach-Object{$c=Trace $_;[pscustomobject]@{label=$labels[$_];value=[double]$c.frameMs;color=$colors[$_]}})
Chart (Join-Path $ChartDirectory 'offline-long-trace-frame-time.png') 'Frame 3000: 6,000-frame sustained offline throughput' $items 21 'ms/frame' 'Lower is better. Every frame uses SubmitNoPresent; WPR GPU tracing runs concurrently.'
$compileItems=@();foreach($n in 'd3d12','wgsl','spirv'){$x=@($a.compileAll|Where-Object case -EQ $n)[0];$compileItems+=@([pscustomobject]@{label="$($n.ToUpper()) Cold";value=[double]$x.coldMs/1000;color='#C6533C'},[pscustomobject]@{label="$($n.ToUpper()) Warm";value=[double]$x.warmMs/1000;color='#33845F'})};Chart (Join-Path $ChartDirectory 'compile-all.png') 'Compile-all: 291 graphics and compute permutations' $compileItems 45 'seconds' 'Cold removes the selected API cache; warm immediately repeats without clearing it.'
$startupItems=@();foreach($n in $order){$cold=Startup $n cold;$warm=Startup $n warm;$startupItems+=@([pscustomobject]@{label="$($labels[$n]) C";value=[double]$cold.firstRuntimeFrameCompleteMs/1000;color='#C6533C'},[pscustomobject]@{label="$($labels[$n]) W";value=[double]$warm.firstRuntimeFrameCompleteMs/1000;color='#33845F'})};Chart (Join-Path $ChartDirectory 'scene-startup.png') 'DayScene first runtime frame: cold and warm caches' $startupItems 13 'seconds' 'Includes asset loading, source preparation, shader modules, and graphics/compute pipeline creation.'
$cellRows=foreach($n in $order){$c=Cell $n;$t=Trace $n;"<tr><td>$(Html $labels[$n])</td><td>$(F $c.completedFrameMs.median 3)</td><td>$(F $c.completedFrameMs.min 3)-$(F $c.completedFrameMs.max 3)</td><td>$(F $c.completedFrameMs.coefficientOfVariationPercent 2)%</td><td>$(F $c.completedFps.median 2)</td><td>$(F $t.frameMs 3)</td><td>$(F $t.engine3d.mean 1)%</td></tr>"}
$deltaRows=foreach($d in $a.deltas){$class=if($d.deltaMs-gt0){'slower'}else{'faster'};$sign=if($d.deltaMs-ge0){'+'}else{''};$psign=if($d.deltaPercent-ge0){'+'}else{''};"<tr><td>$(Html $d.label)</td><td>$(F $d.referenceMs 3)</td><td>$(F $d.candidateMs 3)</td><td class='$class'>$sign$(F $d.deltaMs 3) ms ($psign$(F $d.deltaPercent 2)%)</td></tr>"}
$compileRows=foreach($x in $a.compileAll){"<tr><td>$(Html $x.case.ToUpper())</td><td>$($x.permutations)</td><td>$(F ($x.coldMs/1000) 3) s</td><td>$(F ($x.warmMs/1000) 3) s</td><td>$(F $x.speedup 2)x</td></tr>"}
$startupRows=foreach($n in $order){$cold=Startup $n cold;$warm=Startup $n warm;$source=if($n-like'd3d12*'){Scope $cold 'shader.compile'}elseif($n-like'spirv*'){Scope $cold 'shader.translate.hlsl_spirv_wgsl'}else{Scope $cold 'shader.load'};"<tr><td>$(Html $labels[$n])</td><td>$(F ($cold.firstRuntimeFrameCompleteMs/1000) 3) s</td><td>$(F ($warm.firstRuntimeFrameCompleteMs/1000) 3) s</td><td>$(F ($source/1000) 3) s</td><td>$(F (Scope $cold 'pipeline.create.graphics') 1) ms</td><td>$(F (Scope $cold 'pipeline.create.compute') 1) ms</td></tr>"}
$passNames=[Collections.Generic.List[string]]::new()
$dayScenePassOrder=@('Shadow Depth','GBuffer','Shadow Accumulation','Shadow Blur V','Shadow Blur H','Deferred','Deferred Light Volumes','Opaque Scene Copy','Forward Transparent','God Rays','God Rays Blur V','God Rays Blur H','Light Add','Adapt Luminance','Store Adapted Luminance','Bright','Bloom Blur H','Bloom Blur V','CoC','Combine CoC','DOF','DOF 2','HDR Composition','BackBuffer')
foreach($name in $dayScenePassOrder){if(@($timestamps.runs[0].passes|Where-Object name -EQ $name).Count){$passNames.Add($name)}}
foreach($run in $timestamps.runs){foreach($pass in $run.passes){if(!$passNames.Contains([string]$pass.name)){$passNames.Add([string]$pass.name)}}}
$frameCells=foreach($n in $order){"<td>$(F (TimestampRun $n).medianGpuMs 3)</td>"}
$timestampRows=@("<tr class='frame-row'><td>Whole submitted frame</td>$($frameCells-join'')</tr>")
foreach($passName in $passNames){
  $passCells=foreach($n in $order){$pass=@((TimestampRun $n).passes|Where-Object name -EQ $passName)[0];if($pass){"<td>$(F $pass.medianGpuMs 3)</td>"}else{'<td>-</td>'}}
  $timestampRows+="<tr><td>$(Html $passName)</td>$($passCells-join'')</tr>"
}
$d3d=($a.deltas|Where-Object label -EQ 'D3D12 compute minus raster');$wgsl=($a.deltas|Where-Object label -EQ 'WGSL compute minus raster');$spirv=($a.deltas|Where-Object label -EQ 'SPIR-V compute minus raster')
$reportDir=Split-Path $ReportPath -Parent;$chartRel=[IO.Path]::GetRelativePath($reportDir,$ChartDirectory).Replace('\','/')
$timestampSection=@"
<section><h2>GPU Time by Render Pass</h2><p>Median-of-run-medians timestamp duration across $($timestamps.repetitions) independent runs with $($timestamps.samplesPerRun) held samples per run at frame 3000. Values are milliseconds. The whole-frame interval brackets all submitted frame commands; pass rows bracket each logical render-graph node. Exact zero denotes an executed node with no GPU work for this scene.</p><div class="scroll"><table><thead><tr><th>Pass</th><th>D3D12 Raster</th><th>D3D12 Compute</th><th>WGSL Raster</th><th>WGSL Compute</th><th>SPIR-V Raster</th><th>SPIR-V Compute</th></tr></thead><tbody>$($timestampRows-join'')</tbody></table></div><p class="note">Each pass uses an explicit start/end timestamp query pair in graph execution order. Dawn closes an active physical pass at a logical timestamp boundary because encoder-level <code>WriteTimestamp</code> cannot execute inside a pass. Compare Dawn raster and compute within this instrumented mode; do not mix these values with the lower-overhead whole-frame-only run.</p></section>
"@
$nativeTimestamp=[double](TimestampRun 'd3d12-raster').medianGpuMs
$dawnTimestamp=[double](TimestampRun 'wgsl-raster').medianGpuMs
$timestampWinner=if($nativeTimestamp-le$dawnTimestamp){'Native D3D12'}else{'Dawn WGSL'}
$timestampAdvantage=100*[math]::Abs($nativeTimestamp-$dawnTimestamp)/[math]::Max($nativeTimestamp,$dawnTimestamp)
$nativeThroughput=[double](Cell 'd3d12-raster').completedFrameMs.median
$dawnThroughput=[double](Cell 'wgsl-raster').completedFrameMs.median
$throughputWinner=if($nativeThroughput-le$dawnThroughput){'Native D3D12'}else{'Dawn WGSL'}
$throughputAdvantage=100*[math]::Abs($nativeThroughput-$dawnThroughput)/[math]::Max($nativeThroughput,$dawnThroughput)
$nativeUtil=[double](Trace 'd3d12-raster').engine3d.mean
$dawnUtil=[double](Trace 'wgsl-raster').engine3d.mean
$backendInterpretation=@"
<section><h2>Backend Interpretation</h2><p>Raster GPU timestamps favor <strong>$timestampWinner</strong>: native D3D12 is $(F $nativeTimestamp 3) ms and Dawn WGSL is $(F $dawnTimestamp 3) ms, a $(F $timestampAdvantage 2)% difference relative to the slower result. Completed throughput instead favors <strong>$throughputWinner</strong> by only $(F $throughputAdvantage 2)% ($(F $nativeThroughput 3) versus $(F $dawnThroughput 3) ms/frame). These metrics are not contradictory: timestamps isolate GPU queue execution, while completed throughput also includes CPU recording, submission, queueing, and final drain.</p><p>Per-process 3D-engine counters average $(F $nativeUtil 1)% for native D3D12 and $(F $dawnUtil 1)% for Dawn WGSL. The utilization difference indicates different GPU feeding/scheduling behavior in this offscreen path. It does not prove one API is universally faster. Pass-profile mode also closes Dawn physical passes at logical timestamp boundaries, so compare timestamp cells only within the same instrumented mode.</p><p>Five authored passes switch from fullscreen pixel draws to 8x8 compute dispatches: God Rays, both God Rays blurs, Bright, and HDR Composition. Engine topology is adapter-specific; inspect counter instance names rather than assuming a separate compute engine.</p></section>
"@
$html=@"
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DayScene ARM64 Offline GPU Performance Report</title><style>:root{--ink:#172126;--muted:#56656d;--line:#cad4d9;--paper:#f5f7f8;--panel:#fff;--accent:#246b78;--hot:#b7442e;--good:#246b52}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 "Segoe UI",sans-serif;letter-spacing:0}header{background:#16343d;color:#fff;padding:42px max(24px,calc((100% - 1180px)/2)) 36px;border-bottom:5px solid #d48b3d}header h1{font-size:38px;margin:0 0 8px}header p{margin:0;color:#d9e6e9;font-size:18px}.wrap{max-width:1180px;margin:auto;padding:30px 24px 60px}section{margin:0 0 36px}h2{font-size:25px;border-bottom:2px solid var(--line);padding-bottom:7px}.lede{font-size:19px;max-width:920px}.callouts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.callout{background:#fff;border-left:5px solid var(--accent);padding:18px;box-shadow:0 1px 4px #0001}.callout strong{display:block;font-size:24px}.callout span{color:var(--muted)}table{width:100%;border-collapse:collapse;background:#fff;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:9px 11px;border-bottom:1px solid #dce3e6}th:first-child,td:first-child{text-align:left}th{background:#e8eef0}.slower{color:var(--hot);font-weight:650}.faster{color:var(--good);font-weight:650}.chart{display:block;width:100%;height:auto;background:#fff;border:1px solid var(--line);margin:12px 0 26px}.note{background:#e8eef0;border-left:4px solid #627b86;padding:14px 18px}.warn{background:#fff4e8;border-left-color:#c8772c}code{background:#e8eef0;padding:2px 5px;overflow-wrap:anywhere;word-break:break-word}.scroll{overflow-x:auto}@media(max-width:760px){header h1{font-size:30px}.callouts{grid-template-columns:1fr}.wrap{padding:22px 14px}table{font-size:13px}th,td{padding:7px 5px}}</style></head><body><header><h1>DayScene ARM64 Offline GPU Performance</h1><p>Native D3D12 vs Dawn strict WGSL vs HLSL/SPIR-V; raster vs compute, with no compositor presents</p></header><main class="wrap"><section><p class="lede">This replacement report removes the invalid 60 Hz presentation constraint from the original analysis. Every measured frame is rendered to offscreen targets and submitted with <code>SubmitNoPresent</code>. Timing ends only after <code>WaitForGPU</code>, so it includes command recording/submission plus completed GPU work, but no DWM or swapchain pacing.</p><div class="callouts"><div class="callout"><strong>0 presents</strong><span>PresentMon independently confirmed for D3D12 and Dawn sanity runs</span></div><div class="callout"><strong>600 frames x 5</strong><span>Primary repetitions per cell at held frame 3000</span></div><div class="callout"><strong>6,000 frames</strong><span>Sustained WPR GPU trace per cell; all ETLs zero-loss</span></div></div></section><section><h2>Completed Throughput</h2><div class="scroll"><table><thead><tr><th>Cell</th><th>Median ms/frame</th><th>Run range</th><th>CV</th><th>Median FPS</th><th>6,000-frame ms</th><th>3D engine</th></tr></thead><tbody>$($cellRows-join'')</tbody></table></div><img class="chart" src="$chartRel/offline-five-run-frame-time.png" alt="Five-run offline frame time"><img class="chart" src="$chartRel/offline-long-trace-frame-time.png" alt="Long offline frame time"><div class="scroll"><table><thead><tr><th>Comparison</th><th>Reference</th><th>Candidate</th><th>Delta</th></tr></thead><tbody>$($deltaRows-join'')</tbody></table></div><p class="note">Compute is consistently slower: D3D12 $(F $d3d.deltaMs 3) ms ($(F $d3d.deltaPercent 2)%), WGSL $(F $wgsl.deltaMs 3) ms ($(F $wgsl.deltaPercent 2)%), and SPIR-V $(F $spirv.deltaMs 3) ms ($(F $spirv.deltaPercent 2)%). Strict WGSL and strict SPIR-V are effectively tied after compilation.</p></section><section><h2>Backend Interpretation</h2><p>Dawn is 12-13% faster than native D3D12 in this completed-throughput test. This is <strong>not</strong> a pure shader-execution result: the timing includes backend command recording and submission. ETW counters show Dawn at roughly 98-100% 3D-engine utilization while native D3D12 averages about 89%, indicating native D3D12 underfeeds the GPU in this particular offscreen path. The result should be interpreted as end-to-end backend throughput, not isolated GPU kernel time.</p><p>The Adreno exposes a unified 3D engine for these dispatches; the separate compute-engine counter remains unused. Five authored passes switch from fullscreen pixel draws to 8x8 compute dispatches: God Rays, both God Rays blurs, Bright, and HDR Composition.</p></section><section><h2>Shader Compilation</h2><div class="scroll"><table><thead><tr><th>Path</th><th>Permutations</th><th>Cold</th><th>Warm</th><th>Speedup</th></tr></thead><tbody>$($compileRows-join'')</tbody></table></div><img class="chart" src="$chartRel/compile-all.png" alt="Compile all costs"><h3>Real Scene Startup</h3><div class="scroll"><table><thead><tr><th>Cell</th><th>Cold first frame</th><th>Warm first frame</th><th>Cold source work</th><th>Graphics PSO</th><th>Compute PSO</th></tr></thead><tbody>$($startupRows-join'')</tbody></table></div><img class="chart" src="$chartRel/scene-startup.png" alt="Startup costs"></section><section><h2>Method and Validation</h2><ul><li>Target: <code>$($a.capture.machine)</code>, native ARM64 Release, 1920x1080 DayScene scene 1.</li><li>Fixed timestep reaches runtime frame 3000; simulation and physics then freeze at delta zero.</li><li>Primary runs: five alternating-order launches, 600 identical frames per cell.</li><li>Sustained runs: 6,000 identical frames with WPR GPU and per-process GPU-engine counters.</li><li>Every frame uses offscreen targets and <code>SubmitNoPresent</code>; completion marker follows <code>WaitForGPU</code>.</li><li>PresentMon-attached D3D12 and Dawn sanity runs each observed exactly zero process present rows.</li><li>All six ETLs report zero lost buffers and zero lost events.</li></ul></section><section><h2>Correction</h2><p class="note warn">The previous version of this report used a 60 Hz fixed-step wall-clock pacer and was invalid as an uncapped throughput comparison. Its conclusions are superseded by this report. The retained old archive is historical rejected evidence only.</p></section><section><h2>Limits</h2><p>This metric is GPU-drained completed-frame throughput, not per-pass GPU timestamps. It includes CPU command generation/submission and GPU execution. WPR engine utilization supports saturation analysis but cannot isolate individual pass duration. PIX or a future WebGPU timestamp backend is required for pure per-pass GPU attribution.</p><p>Executable SHA-256: <code>$($a.capture.executableSha256)</code>.</p></section></main></body></html>
"@
$html=$html.Replace('.slower{','.frame-row{font-weight:700;background:#edf4f5}.slower{')
$html=$html.Replace('<section><h2>Completed Throughput</h2>',"$timestampSection<section><h2>Completed Throughput</h2>")
$html=[regex]::Replace($html,'<section><h2>Backend Interpretation</h2>.*?</section>',$backendInterpretation,[Text.RegularExpressions.RegexOptions]::Singleline)
$html=$html.Replace('This metric is GPU-drained completed-frame throughput, not per-pass GPU timestamps. It includes CPU command generation/submission and GPU execution. WPR engine utilization supports saturation analysis but cannot isolate individual pass duration. PIX or a future WebGPU timestamp backend is required for pure per-pass GPU attribution.','The render-pass table is timestamp-derived GPU execution time. The completed-throughput section remains a separate CPU command generation/submission plus GPU-drain metric. Pass medians do not sum exactly to the whole-frame median because medians are computed independently and the frame interval also includes barriers, transitions, resolves, and commands outside render-graph nodes.')
$html=$html.Replace('DayScene ARM64 Offline GPU Performance',"DayScene $architecture Offline GPU Performance")
$html=$html.Replace('native ARM64 Release',"native $architecture Release")
$html=$html.Replace('ETW counters show','Per-process GPU Engine counters show')
if($etlCount-ne6){
  $html=$html.Replace('Sustained WPR GPU trace per cell; all ETLs zero-loss','Sustained GPU Engine counter run per cell; WPR ETL unavailable')
  $html=$html.Replace('Sustained runs: 6,000 identical frames with WPR GPU and per-process GPU-engine counters.','Sustained runs: 6,000 identical frames with per-process GPU-engine counters; WPR was privilege-blocked.')
  $html=$html.Replace('All six ETLs report zero lost buffers and zero lost events.','WPR ETLs are unavailable on this host; this is a degraded counter-only trace phase.')
}else{
  $etlValidator=@($a.traces|Where-Object{$_.etl.available}|Select-Object -ExpandProperty etl|Select-Object -ExpandProperty validatedOnMachine -Unique) -join ', '
  if($etlValidator){$html=$html.Replace('All six ETLs report zero lost buffers and zero lost events.',"All six ETLs report zero lost buffers and zero lost events; xperf validation ran on <code>$(Html $etlValidator)</code>.")}
}
[IO.File]::WriteAllText($ReportPath,$html,[Text.UTF8Encoding]::new($false));Write-Output "Offline report written: $ReportPath"
